package in.asmj.ride.model;
import org.springframework.data.annotation.Id;import org.springframework.data.mongodb.core.mapping.Document;import java.time.Instant;
@Document("rentalReviews") public class RentalReview { @Id private String id; private String bookingId,customerId,vehicleId,ownerId,agentId,driverId,comment; private int vehicleRating,providerRating,driverRating; private Instant createdAt=Instant.now();
public String getId(){return id;} public void setId(String v){id=v;} public String getBookingId(){return bookingId;} public void setBookingId(String v){bookingId=v;} public String getCustomerId(){return customerId;} public void setCustomerId(String v){customerId=v;} public String getVehicleId(){return vehicleId;} public void setVehicleId(String v){vehicleId=v;} public String getOwnerId(){return ownerId;} public void setOwnerId(String v){ownerId=v;} public String getAgentId(){return agentId;} public void setAgentId(String v){agentId=v;} public String getDriverId(){return driverId;} public void setDriverId(String v){driverId=v;} public String getComment(){return comment;} public void setComment(String v){comment=v;} public int getVehicleRating(){return vehicleRating;} public void setVehicleRating(int v){vehicleRating=v;} public int getProviderRating(){return providerRating;} public void setProviderRating(int v){providerRating=v;} public int getDriverRating(){return driverRating;} public void setDriverRating(int v){driverRating=v;} public Instant getCreatedAt(){return createdAt;} }
